text:
query {
  user(id: 1) {
    name
    email
  }
}

query GetPosts($limit: Int!) {
  posts(first: $limit) {
    id
    title
    author { name }
  }
}

type User {
  id: ID!
  name: String!
  posts: [Post!]!
}

type Mutation {
  createPost(title: String!, authorId: ID!): Post
}

query {
  posts {
    id
    title
  }
}

mutation {
  createUser(name: "Ann") {
    id
    name
  }
}

fragment UserFields on User {
  id
  name
  email
}

query {
  me { ...UserFields }
}

input NewPost {
  title: String!
  body: String
  tags: [String!]
}

query Feed($withAuthor: Boolean!, $skipBody: Boolean!) {
  posts {
    title
    body @skip(if: $skipBody)
    author @include(if: $withAuthor) { name }
  }
}

enum Role { ADMIN USER GUEST }

interface Node {
  id: ID!
}

type Account implements Node {
  id: ID!
  role: Role!
}

union SearchResult = User | Post | Comment

type Subscription {
  postAdded(authorId: ID): Post!
}

query Page($after: String) {
  posts(first: 10, after: $after) {
    edges { cursor node { id title } }
    pageInfo { hasNextPage endCursor }
  }
}

query {
  user(id: "1") {
    name
    posts {
      title
    }
  }
}

query {
  first: user(id: 1) { name }
  second: user(id: 2) { name }
}

type Book {
  title: String
  pages: Int
  rating: Float
  inStock: Boolean
}

mutation {
  deletePost(id: 7) {
    success
  }
}

mutation AddTodo($text: String!) {
  addTodo(text: $text) {
    id
    text
    done
  }
}

type Query {
  user(id: ID!): User
  users(limit: Int = 10): [User!]!
  search(term: String!): [SearchResult!]
}

query {
  search(term: "graph") {
    ... on Post { title }
    ... on User { name }
    __typename
  }
}

const resolvers = {
  Query: {
    user: (_, { id }, { db }) => db.users.find(id),
  },
  User: {
    posts: user => db.posts.filter(p => p.authorId === user.id),
  },
};
